-- A description for each of the 205 products that were live on 16 Nov 2026 (shown under "Product details" on the
-- product page). Run after update 055, which adds products.description. Safe to run again: it fills a
-- description only where none is written, so anything changed in Admin → Products is kept.
-- Sizes of the same product share one description. A product not in this list keeps the general line for its category.

-- First: four products whose letters broke when an earlier SQL was pasted ("Lakm" + broken "e" in one name,
-- a broken "x" sign in three pack sizes). Written with character codes so it cannot break again.
update public.products set name = replace(name, chr(8730) || chr(169), chr(233)), updated_at = now() where name like '%' || chr(8730) || chr(169) || '%';
update public.products set size = replace(size, chr(8730) || chr(243), chr(215)), updated_at = now() where size like '%' || chr(8730) || chr(243) || '%';

update public.products p set description = v.description, updated_at = now()
